bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker logs --tail 150 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || exit 62
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {reconcileStickerRegistration} from './src/stickers/packRegistration.mjs';
const e=process.env;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:5000});
const out=createCreatorTelegramFetch(globalThis.fetch);
try{
 const {rows}=await pool.query(
  "SELECT r.pack_name,r.kind,r.file_unique_id,r.uploaded_file_unique_id,r.phase,s.state->'stickerPending'->>'setName' AS existing_name,s.state->'stickerPending'->>'title' AS title FROM videobot_sticker_registration_receipts r JOIN videobot_creator_sessions s ON s.owner_user_id=r.owner_user_id WHERE r.phase='needs_reconcile' ORDER BY r.updated_at DESC LIMIT 1");
 if(rows.length!==1){process.exitCode=80;}
 else{
  const r=rows[0];
  if(r.uploaded_file_unique_id!==r.file_unique_id||r.existing_name!==null){process.exitCode=81;}
  else{
   const api=createTelegramBotApi({
    token:readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim(),
    fetchImpl:out.fetch,timeoutMs:15000});
   const result=await reconcileStickerRegistration({
    telegramApi:api,name:r.pack_name,kind:r.kind,format:'static',
    fileUniqueId:r.file_unique_id,expectedTitle:r.title,isNewPack:true});
   process.exitCode=result.verified===true&&result.proof==='unique_new_pack'&&
     result.item?.file_unique_id!==r.file_unique_id?0:82;
  }
 }
}catch{process.exitCode=70;}
finally{await out.close();await pool.end();}
NODE
